import AppKit
import UniformTypeIdentifiers

public enum CopyKind: Equatable, Sendable {
    case items(files: Int, folders: Int)
    case paths(Int)
    case concealed
    case other
}

public enum ClipboardInspector {
    /// Markers that password managers and other apps use for private or temporary copies.
    private static let sensitiveTypes: Set<NSPasteboard.PasteboardType> = Set([
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
        "net.antelle.keeweb",
    ].map { NSPasteboard.PasteboardType($0) })

    /// Longer text is not Finder path text worth counting, and parsing it would stall the app.
    static let maxPathTextBytes = 2_000_000

    /// Works out what was copied. Returns only a kind and counts, never content.
    @MainActor
    public static func inspect(_ pasteboard: NSPasteboard) -> CopyKind {
        let changeCount = pasteboard.changeCount
        let kind = read(pasteboard)
        // If the clipboard changed mid-read, the result may mix two copies, so discard it.
        return pasteboard.changeCount == changeCount ? kind : .other
    }

    @MainActor
    private static func read(_ pasteboard: NSPasteboard) -> CopyKind {
        let types = pasteboard.types ?? []

        // Decided from type names alone, so sensitive data is never read.
        if !sensitiveTypes.isDisjoint(with: types) { return .concealed }

        if types.contains(.fileURL) {
            let options: [NSPasteboard.ReadingOptionKey: Any] = [.urlReadingFileURLsOnly: true]
            let urls = pasteboard.readObjects(forClasses: [NSURL.self], options: options) as? [URL] ?? []
            guard !urls.isEmpty else { return .other }
            let folders = urls.filter(isPlainFolder).count
            return .items(files: urls.count - folders, folders: folders)
        }

        if types.contains(.string), let text = pasteboard.string(forType: .string) {
            return classify(text: text)
        }
        return .other
    }

    /// Finder shows apps and packages as single files. Uses only the URL, so the sandbox stays tight.
    private static func isPlainFolder(_ url: URL) -> Bool {
        guard url.hasDirectoryPath else { return false }
        // Unknown extensions get an undeclared placeholder type, so only declared types count.
        guard let type = UTType(filenameExtension: url.pathExtension, conformingTo: .package) else { return true }
        return !type.isDeclared
    }

    static func classify(text: String) -> CopyKind {
        guard text.utf8.count <= maxPathTextBytes,
              let first = text.first(where: { !$0.isWhitespace }),
              first == "/" || first == "'",
              let count = countPaths(in: text), count > 0 else { return .other }
        return .paths(count)
    }

    /// Counts paths in Finder's Copy as Pathname text, or returns nil if it isn't that format.
    /// Finder separates several paths with spaces and single-quotes those containing spaces,
    /// for example: '/a/my file.txt' /a/b.txt /a/c.txt. A lone path may be unquoted with spaces.
    private static func countPaths(in text: String) -> Int? {
        let chars = Array(text)
        var index = 0
        var count = 0

        while true {
            while index < chars.count, chars[index].isWhitespace { index += 1 }
            guard index < chars.count else { return count }

            if chars[index] == "'" {
                guard index + 1 < chars.count, chars[index + 1] == "/" else { return nil }
                index += 1
                while true {
                    guard index < chars.count else { return nil } // Unterminated quote.
                    if chars[index] != "'" {
                        index += 1
                    } else if index + 3 < chars.count, String(chars[(index + 1)...(index + 3)]) == "\\''" {
                        index += 4 // An escaped apostrophe: '\''
                    } else {
                        index += 1
                        break
                    }
                }
                guard index == chars.count || chars[index].isWhitespace else { return nil }
            } else if chars[index] == "/" {
                while index < chars.count, !chars[index].isNewline, !startsNextPath(chars, at: index) {
                    index += 1
                }
            } else {
                return nil
            }
            count += 1
        }
    }

    private static func startsNextPath(_ chars: [Character], at index: Int) -> Bool {
        guard chars[index] == " ", index + 1 < chars.count else { return false }
        if chars[index + 1] == "/" { return true }
        return chars[index + 1] == "'" && index + 2 < chars.count && chars[index + 2] == "/"
    }
}
